package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.SystemClock;
import android.view.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import java.io.*;
import java.time.*;
import java.util.*;
import java.util.regex.Pattern;
import static org.junit.Assert.*;

/** Silent native journeys against an isolated database. Synthetic fixtures are explicitly labeled. */
@RunWith(AndroidJUnit4.class)
public class HistoryFlowTest {
    private final Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();private final Context c=instrumentation.getTargetContext();private final UiDevice device=UiDevice.getInstance(instrumentation);
    private UiObject2 object(String description){UiObject2 v=device.wait(Until.findObject(By.desc(description)),5000);if(v==null){try{new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(description));}catch(UiObjectNotFoundException ignored){}v=device.wait(Until.findObject(By.desc(description)),1000);}assertNotNull(description,v);return v;}
    private void click(String text){UiObject2 view=device.findObject(By.desc(text));if(view==null)view=device.wait(Until.findObject(By.text(text)),5000);if(view==null)view=device.wait(Until.findObject(By.text(Pattern.compile(Pattern.quote(text),Pattern.CASE_INSENSITIVE))),2000);assertNotNull(text,view);view.click();device.waitForIdle();}
    private void title(String title){assertTrue(title,device.wait(Until.hasObject(By.text(title)),5000));device.waitForIdle();}
    private void capture(String name){device.waitForIdle();SystemClock.sleep(650);instrumentation.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))assertTrue("Cream screens require dark status icons after dialogs",(a.getWindow().getInsetsController().getSystemBarsAppearance()&WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS)!=0);});File dir=new File(c.getExternalFilesDir(null),"verification");assertTrue(dir.isDirectory()||dir.mkdirs());assertTrue(device.takeScreenshot(new File(dir,"history-"+name+".png")));}
    private void launch(Class<?> type,long id){Instrumentation.ActivityMonitor monitor=instrumentation.addMonitor(type.getName(),null,false);try{c.startActivity(new Intent(c,type).putExtra("record",id).putExtra("visualReview",true).putExtra("verificationLabel","VISUAL TEST · isolated sample records").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));assertNotNull(monitor.waitForActivityWithTimeout(5000));instrumentation.waitForIdleSync();device.waitForIdle();}finally{instrumentation.removeMonitor(monitor);}}
    private void open(long id){UiObject2 row=device.wait(Until.findObject(By.descStartsWith("Open record "+id+",")),5000);assertNotNull("History row "+id,row);row.click();title("Edit sleep");object("Notes or dream");}
    private void addTag(String text){click("Add tag");object("Tag name").setText(text);click("Add");}
    private void addAwake(){click("+   Add awake period");title("Awake starts");click("Use time");title("Awake ends");click("Use time");}
    private void recreate(){final Activity[] activity={null};instrumentation.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))activity[0]=a;});assertNotNull(activity[0]);Instrumentation.ActivityMonitor monitor=instrumentation.addMonitor(activity[0].getClass().getName(),null,false);try{instrumentation.runOnMainSync(activity[0]::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));instrumentation.waitForIdleSync();}finally{instrumentation.removeMonitor(monitor);}}
    private void dragStart(){UiObject2 timeline=device.wait(Until.findObject(By.descStartsWith("Editable period from")),5000);assertNotNull(timeline);android.graphics.Rect bounds=timeline.getVisibleBounds();device.swipe(bounds.left+(int)(bounds.width()*.11f),bounds.centerY(),bounds.left+(int)(bounds.width()*.21f),bounds.centerY(),30);device.waitForIdle();}
    private void history(){launch(HistoryActivity.class,0);title("Sleep history");assertTrue(device.wait(Until.gone(By.text("Loading records…")),5000));}
    private String raw(Store store){return store.rows("SELECT * FROM sessions WHERE id=1000").toString()+store.rows("SELECT * FROM epochs WHERE session=1000 ORDER BY time").toString()+store.rows("SELECT * FROM tracking_pauses WHERE session=1000").toString();}
    private void seed(Store store){ZoneId zone=ZoneId.systemDefault();LocalDate today=LocalDate.now(zone);long now=System.currentTimeMillis();for(int n=1;n<=6;n++){long end=today.minusDays(n).atTime(6,30).atZone(zone).toInstant().toEpochMilli();long minutes=n%2==0?450:480;RecordDraft draft=new RecordDraft(end-minutes*60000,end);draft.note="Isolated manually entered test period";draft.rated=true;draft.rating=n%2==0?3:5;if(n==2)draft.addTag("Late meal");Records.create(store,draft,zone,now);}
        long nap=today.minusDays(3).atTime(14,0).atZone(zone).toInstant().toEpochMilli();RecordDraft d=new RecordDraft(nap,nap+1200000);d.addTag("Nap");d.note="Isolated nap test";Records.create(store,d,zone,now);
        long end=today.minusDays(1).atTime(6,30).atZone(zone).toInstant().toEpochMilli(),start=end-462*60000L;store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,active_ms,note,source,origin,zone) VALUES(1000,?,?,?,'Isolated synthetic sensor fixture','tracked','local',?)",new Object[]{start,end,452*60000L,zone.getId()});store.pause(1000,start+180*60000L);store.resume(1000,start+190*60000L);for(int i=0;i<462;i++){if(i>=180&&i<190)continue;store.epoch(1000,start+i*60000L,start+(i+1)*60000L,.02+(i%11)*.013,null,null,300);}
    }
    @Test public void manualDraftSaveSearchTrendsAndTrackedEditsPersist() throws Exception {
        assertFalse("Do not interrupt an alarm",Prefs.flag(c,"ringing"));assertFalse("Do not interrupt recording",TrackingService.running);String name="sleepwell-history-verification-"+UUID.randomUUID()+".db";Records.Factory previous=Records.factory;List<File> owned=new ArrayList<>();Records.factory=context->new Store(context,name);
        try{
            history();title("No records yet");capture("empty");click("Add sleep");title("Add sleep");object("Notes or dream").setText("Verification manual entry");addTag("Late meal");click("Save changes");title("Sleep history");long id;try(Store store=new Store(c,name)){id=Records.all(store).get(0).id;assertTrue(Records.get(store,id).manual());assertTrue(store.rows("SELECT * FROM epochs").isEmpty());}open(id);capture("editor");object("Notes or dream").setText("Unsaved note");dragStart();click("Back");title("Sleep history");open(id);assertEquals("Verification manual entry",object("Notes or dream").getText());addAwake();object("Notes or dream").setText("Saved note and dream");recreate();title("Edit sleep");assertEquals("Saved note and dream",object("Notes or dream").getText());click("Save changes");title("Sleep history");try(Store store=new Store(c,name)){RecordEntry entry=Records.get(store,id);assertEquals(1,entry.edit.awake.size());assertEquals("Saved note and dream",entry.edit.note);assertTrue(entry.edit.tags.contains("Late meal"));}open(id);capture("reopened");click("Record options");click("View recorded signals");title("No sensor measurements");capture("manual-signals");click("Back");title("Edit sleep");click("Delete record");title("Delete this record?");click("Delete record");title("Sleep history");try(Store store=new Store(c,name)){assertTrue(Records.all(store).isEmpty());seed(store);}history();capture("history");
            click("Search records");object("Search notes and tags").setText("Late meal");assertTrue(device.wait(Until.hasObject(By.descStartsWith("Open record ")),5000));capture("search");object("Search notes and tags").setText("does-not-match-anything");title("No matching records");click("Search records");click("Good sleep");title("Your rested rating: 4–5.");capture("filter");click("All");click("Trends");title("Trends");capture("trends-week");click("Month");assertTrue(object("Month").isSelected());capture("trends-month");click("Year");assertTrue(object("Year").isSelected());capture("trends-year");click("Sleep history");title("Sleep history");String before;try(Store store=new Store(c,name)){before=raw(store);}open(1000);dragStart();addAwake();object("Notes or dream").setText("Edited synthetic test fixture");addTag("Exercise");capture("tracked-editor");click("Save changes");title("Sleep history");open(1000);capture("tracked-saved");try(Store store=new Store(c,name)){assertEquals(before,raw(store));RecordEntry changed=Records.get(store,1000);assertTrue(changed.edited);assertTrue(changed.edit.start>changed.rawStart);assertEquals(1,changed.edit.awake.size());assertTrue(changed.duration()<452*60000L);Backup.validate(store.backup());}
            // A short real native edit supports seconds, and deletion removes only its selected test clip.
            long shortStart=System.currentTimeMillis()/60000*60000-120000+10000;File dir=new File(c.getFilesDir(),"clips");assertTrue(dir.isDirectory()||dir.mkdirs());File own=new File(dir,"verification-record-"+UUID.randomUUID()+".wav"),other=new File(dir,"verification-record-"+UUID.randomUUID()+".wav");owned.add(own);owned.add(other);NoiseRecorder.writeWave(own,new byte[320]);NoiseRecorder.writeWave(other,new byte[320]);try(Store store=new Store(c,name)){store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,active_ms,source,origin,zone) VALUES(1001,?,?,30000,'tracked','local',?)",new Object[]{shortStart,shortStart+30000,ZoneId.systemDefault().getId()});store.clip(1001,shortStart+1000,own.getName(),.1);store.clip(1000,shortStart+1000,other.getName(),.1);}
            launch(RecordEditorActivity.class,1001);title("Edit sleep");object("Change start time").click();title("Start");object("Seconds").setText("11");click("Use time");capture("short-editor");click("Save changes");try(Store store=new Store(c,name)){long until=SystemClock.elapsedRealtime()+5000;while(!Records.get(store,1001).edited&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(100);assertEquals(29000,Records.get(store,1001).duration());}launch(RecordEditorActivity.class,1001);title("Edit sleep");object("Notes or dream");click("Delete record");title("Delete this record?");click("Delete record");long until=SystemClock.elapsedRealtime()+5000;while(own.exists()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(100);assertFalse(own.exists());assertTrue(other.exists());try(Store store=new Store(c,name)){assertTrue(store.rows("SELECT * FROM sessions WHERE id=1001").isEmpty());assertEquals(1,store.rows("SELECT * FROM clips WHERE session=1000").size());}
        }finally{
            Records.factory=previous;c.startActivity(new Intent(c,MainActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));instrumentation.waitForIdleSync();device.waitForIdle();c.deleteDatabase(name);for(File file:owned)if(file.exists())assertTrue(file.delete());
        }
    }
}
